#include <stdio.h>
int main(void) {
  int c;
  int running = 0;
  while ((c = getchar()) != '\n') {
    if (c == 's') {
      running = !running;
      if (running) {
        printf("Start ");
      } else {
        printf("Stop ");
      }
    }
  }
  return 0;
}

The user types "uudru" and presses Enter. What is the output?
#include <stdio.h>
int main(void) {
  int c;
  int score = 0;
  while ((c = getchar()) != '\n') {
    switch (c) {
      case 'u': score += 10; break;
      case 'd': score -= 5; break;
      case 'r': score = 0; break;
    }
  }
  printf("%d", score);
  return 0;
}

